function decodeBase64(s) {
  const bin = atob(s.replace(/\s+/g, ""));
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// The GB-Link Team cards, written by tools/native-cards/build.mjs: one payload
// per ROM, as each game, revision and language has its own addresses. All but
// the Master Ball check the ROM header in game and are sent only to the ROMs
// they list. The Master Ball's two scripts differ only in the flag and var
// numbers each game uses.
const EMERALD_ROMS = ['BPEE 1.0', 'BPEF 1.0', 'BPED 1.0', 'BPEI 1.0', 'BPES 1.0', 'BPEJ 1.0'];
const FRLG_ROMS = ['BPRE 1.0', 'BPRE 1.1', 'BPGE 1.0', 'BPGE 1.1', 'BPRF 1.0', 'BPRD 1.0', 'BPRI 1.0', 'BPRS 1.0', 'BPGF 1.0', 'BPGD 1.0', 'BPGI 1.0', 'BPGS 1.0', 'BPRJ 1.0', 'BPRJ 1.1', 'BPGJ 1.0', 'BPGJ 1.1'];
const NATIVE_ROMS = [...EMERALD_ROMS, ...FRLG_ROMS];

// A game's payloads: its base ROM's, and for each other ROM the bytes that
// differ from it, as runs of [u16 offset, u8 length, bytes].
function romPayloads(baseRom, base, patches) {
  const payloads = { [baseRom]: [base] };
  for (const [rom, diff] of Object.entries(patches)) {
    const bytes = Uint8Array.from(base);
    for (let at = 0; at < diff.length; at += 3 + diff[at + 2]) {
      bytes.set(diff.subarray(at + 3, at + 3 + diff[at + 2]), diff[at] | (diff[at + 1] << 8));
    }
    payloads[rom] = [bytes];
  }
  return payloads;
}

